SELECT * FROM (SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Charged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='CH')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Heating Completed' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='HT')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Discharged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='DS')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Rough Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='RR')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'ROP:'||operation_id event_id,'Finish Rolling Completed' activity,finished_at timestamp,operation_id source_key FROM rolling_operation_history WHERE finished_at IS NOT NULL AND (phase_code='FR')) e JOIN rolling_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Leveling Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='LEV')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Heat Treatment Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='HT')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'E:'||s.equipment_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Surface Finishing Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='SF')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key) ORDER BY case_id,timestamp,event_id;
